  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

// Totals are floored to whole euros, after the discount.
test('no discount at or below 100, total floored', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 1 }]), 10)
  assert.equal(await totalOf([{ sku: 'B', qty: 3 }]), 76) // 76.5
  assert.equal(await totalOf([{ sku: 'C', qty: 5 }]), 0) // 0.5
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100) // boundary: not discounted
})

test('10% discount only when raw total is strictly above 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 90) // 101 -> 90.9 floored
  assert.equal(await totalOf([{ sku: 'A', qty: 100 }]), 900)
})

test('discount applies to the whole order, flat, no tiers for larger orders', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 1000 }]), 9000)
  assert.equal(await totalOf([{ sku: 'A', qty: 6 }, { sku: 'B', qty: 2 }]), 100) // 111 -> 99.9 -> 99? see below
})

test('mixed items sum before discount; fractional results floored', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 4 }]), 119) // 133.32 -> 119.988 -> 119
})

test('order is stored and retrievable', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 2 }] })).json()
  const got = await (await fetch(`${base}/orders/${created.id}`)).json()
  assert.deepEqual(got, created)
  assert.deepEqual(created.items, [{ sku: 'A', qty: 2 }])
})

test('validation and routing quirks', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  const bad = await fetch(`${base}/orders`, { method: 'POST', body: '{nope' })
  assert.equal(bad.status, 400)
  const missing = await fetch(`${base}/orders/999`)
  assert.equal(missing.status, 200) // quirk: not-found is a 200
  assert.deepEqual(await missing.json(), { error: 'not found' })
  assert.equal((await fetch(`${base}/nope`)).status, 404)
})

test('quirks: negative qty and unknown sku are not rejected', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: -2 }]), -20)
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null) // NaN serialises as null
})
